import { useParams } from 'react-router-dom'
import ProductsList from '../../components/ProductsList'
import ladocevita from '../../assets/pratos/La Dolce Vita Trattoria/image 1.png'
import Pratos from '../../models/Pratos'
import Banner from '../../components/Banner'

// Dados do prato La Dolce Vita
const pratoDolceVita: Pratos = {
  id: 2,
  title: 'La Dolce Vita Trattoria',
  nota: 10,
  description:
    'A La Dolce Vita Trattoria leva a autêntica cozinha italiana até você! Desfrute de massas caseiras, pizzas deliciosas e risotos incríveis, tudo no conforto do seu lar. Entrega rápida, pratos bem embalados e sabor inesquecível. Peça já!',
  image: ladocevita,
  infos: ['Italiana']
}

const LaDolceVita = () => {
  const { id } = useParams()

  return (
    <>
      <Banner />
      <h2>{pratoDolceVita.title}</h2>
      <ProductsList
        pratos={[pratoDolceVita]}
        title="Detalhes do Prato"
        background="gray"
      />
    </>
  )
}

export default LaDolceVita
